{"path":"index.html","content":"<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width,initial-scale=1">
  <title>{{BUSINESS_NAME}} — Restorative care for busy minds</title>
  <meta name="description" content="Practical, person-centered coaching and therapeutic sessions that help you map calmer days. Educational, evidence-informed approaches without promises of cure.">
  <link rel="stylesheet" href="assets/css/styles.css">
</head>
<body class="page-root">
  <svg class="scene-pattern" aria-hidden="true">
    <use href="assets/img/pattern.svg#pattern"></use>
  </svg>

  <header class="site-header" role="banner">
    <div class="container header-inner">
      <a class="brand" href="/">{{BUSINESS_NAME}}</a>
      <nav class="nav" role="navigation" aria-label="Main">
        <ul>
          <li><a href="services.html">Offerings</a></li>
          <li><a href="approach.html">Method</a></li>
          <li><a href="conditions.html">Conditions</a></li>
          <li><a href="about.html">About</a></li>
          <li><a href="pricing.html">Investment</a></li>
          <li><a class="cta" href="book.html">{{PRIMARY_CTA_LABEL}}</a></li>
        </ul>
      </nav>
    </div>
  </header>

  <main>
    <!-- HERO -->
    <section class="hero reveal" data-reveal>
      <div class="container">
        <h1 class="hero-head">Thoughtful, layered care that meets your life where it is.</h1>
        <p class="hero-sub">Small, practical steps and a map that adapts as you move—educational guidance for stress, sleep, digestion, and energy regulation.</p>
        <div class="hero-actions">
          <a class="btn primary" href="book.html">Plan your first session</a>
          <a class="btn ghost" href="contact.html">Ask a question</a>
        </div>
      </div>
    </section>

    <!-- STORY -->
    <section class="story reveal" data-reveal>
      <div class="container two-col">
        <div>
          <h2>How we think about care</h2>
          <p>We stitch together evidence-informed practices—movement, breath work, nutrition sensemaking, and coaching—to create manageable routines. The aim: a steadier baseline, not dramatic guarantees. You keep authorship; we help clarify the next right steps.</p>
          <p class="muted">Sessions are educational and supportive. Recommendations are collaborative and tailored.</p>
        </div>
        <aside>
          <h3>In one sentence</h3>
          <p>A simple, stepwise plan you can try for four weeks and adapt from there.</p>
        </aside>
      </div>
    </section>

    <!-- FRAMEWORK -->
    <section class="framework reveal" data-reveal>
      <div class="container">
        <h2>Our working frame</h2>
        <ol class="frame-list">
          <li><strong>Listen:</strong> Learn what matters most in your life right now.</li>
          <li><strong>Map:</strong> Build a practical rhythm of actions and experiments.</li>
          <li><strong>Practice:</strong> Small daily anchors you can sustain.</li>
          <li><strong>Adjust:</strong> Evaluate and refine with measurable signs.</li>
        </ol>
        <p class="note">This is educational support and not a substitute for medical care. For urgent needs, contact local services.</p>
      </div>
    </section>

    <!-- OFFERS (with Session Planner) -->
    <section class="offers reveal" data-reveal>
      <div class="container two-col">
        <div>
          <h2>Programs & session types</h2>
          <p>We work in modular packages so each plan fits your schedule and budget. Choose consultation, short-series, or ongoing stewardship.</p>
          <ul class="offer-list">
            <li><strong>Foundation Consult</strong> — 60 min discussion, focused recommendations and a starter plan.</li>
            <li><strong>Four-Week Starter</strong> — 4 sessions + check-ins; structured trials and learning tasks.</li>
            <li><strong>Care Stewardship</strong> — month-to-month support for people who want ongoing adjustments and accountability.</li>
          </ul>
          <p class="muted">Modalities include coaching, lifestyle guidance, breath and movement strategies, and care coordination suggestions.</p>
        </div>

        <aside class="planner" aria-labelledby="planner-head">
          <h3 id="planner-head">Session Planner</h3>
          <p class="muted">Build a concise plan to bring to your first meeting. This is a tool for reflection and planning—not a medical record.</p>

          <label>Primary concern
            <textarea id="sp-concern" rows="3" placeholder="Describe what's most pressing"></textarea>
          </label>

          <fieldset>
            <legend>Goals (pick up to 3)</legend>
            <label><input type="checkbox" name="goal" value="Better sleep"> Better sleep</label>
            <label><input type="checkbox" name="goal" value="Less anxiety"> Less anxiety</label>
            <label><input type="checkbox" name="goal" value="More energy"> More energy</label>
            <label><input type="checkbox" name="goal" value="Digestive ease"> Digestive ease</label>
            <label><input type="checkbox" name="goal" value="Clearer focus"> Clearer focus</label>
          </fieldset>

          <label>Time you can commit per week
            <input id="sp-time" type="range" min="0" max="10" value="2">
            <div class="range-value"><span id="sp-time-val">2</span> hours</div>
          </label>

          <label>Budget comfort
            <select id="sp-budget">
              <option value="low">Intro / constrained</option>
              <option value="medium" selected>Moderate</option>
              <option value="high">Ample</option>
            </select>
          </label>

          <fieldset>
            <legend>Preferences</legend>
            <label><input type="checkbox" id="mod-coach"> Coaching</label>
            <label><input type="checkbox" id="mod-nutrition"> Practical nutrition sensemaking</label>
            <label><input type="checkbox" id="mod-movement"> Movement & breath</label>
            <label><input type="checkbox" id="mod-tele"> Short telecheck-ins</label>
          </fieldset>

          <div class="planner-actions">
            <button id="sp-generate" class="btn primary">Generate plan</button>
            <button id="sp-copy" class="btn ghost" disabled>Copy summary</button>
          </div>

          <label aria-hidden="true">Summary
            <textarea id="sp-summary" rows="6" readonly placeholder="Your plan will appear here."></textarea>
          </label>
        </aside>
      </div>
    </section>

    <!-- PRICING -->
    <section class="pricing reveal" data-reveal>
      <div class="container">
        <h2>Investment</h2>
        <p>We frame pricing as flexible tiers so you can choose what matches your aims.</p>
        <div class="pricing-grid">
          <div class="card">
            <h3>Intro Session</h3>
            <p class="price">$120</p>
            <p>One 60-minute focused consult and a starter plan.</p>
          </div>
          <div class="card featured">
            <h3>Starter Path</h3>
            <p class="price">$420</p>
            <p>4-session program with short check-ins and a measurable 4-week experiment.</p>
          </div>
          <div class="card">
            <h3>Stewardship</h3>
            <p class="price">Custom</p>
            <p>Ongoing monthly support for adaptive plans and accountability.</p>
          </div>
        </div>
        <p class="muted">If cost is a barrier, ask about sliding options at your first contact.</p>
      </div>
    </section>

    <!-- TESTIMONIALS -->
    <section class="testimonials reveal" data-reveal>
      <div class="container">
        <h2>Words from people who worked with us</h2>
        <blockquote>"Concrete, doable suggestions that actually fit my week. I slept better in two weeks." — A client in {{CITY}}, {{STATE}}</blockquote>
        <blockquote>"A kind, practical approach that didn't overpromise." — Another client</blockquote>
      </div>
    </section>

    <!-- CTA -->
    <section class="final-cta reveal" data-reveal>
      <div class="container">
        <h2>Ready to start?</h2>
        <p>Book a short consult or send a quick note to see if we fit.</p>
        <div class="hero-actions">
          <a class="btn primary" href="book.html">Reserve a spot</a>
          <a class="btn ghost" href="contact.html">Send a question</a>
        </div>
      </div>
    </section>
  </main>

  <footer class="site-footer">
    <div class="container">
      <div class="foot-left">© <span id="yr"></span> {{BUSINESS_NAME}}</div>
      <div class="foot-right">Contact: <a href="tel:{{PHONE}}">{{PHONE}}</a> • <a href="mailto:{{EMAIL}}">{{EMAIL}}</a></div>
    </div>
  </footer>

  <script src="assets/js/main.js"></script>
</body>
</html>"} 
