{"path":"assets/css/styles.css","content":"/* Core styles - minimal, poetic cadence */
:root{
  --bg:#fbfbfa;
  --ink:#112;
  --muted:#586;
  --accent:#6c8;
  --accent-2:#6ca;
  --card:#fff;
  --radius:12px;
  --gap:20px;
  --max-width:1100px;
}
*{box-sizing:border-box}
html,body{height:100%;margin:0;background:var(--bg);color:var(--ink);font-family:system-ui,-apple-system,Segoe UI,Roboto,'Helvetica Neue',Arial;line-height:1.45}
.container{max-width:var(--max-width);margin:0 auto;padding:48px 24px}
.header-inner{display:flex;align-items:center;justify-content:space-between}
.brand{font-weight:700;text-decoration:none;color:var(--ink);font-size:1.05rem}
.nav ul{list-style:none;margin:0;padding:0;display:flex;gap:14px}
.nav a{color:var(--ink);text-decoration:none;padding:8px 10px;border-radius:8px}
.nav a.cta{background:linear-gradient(90deg,var(--accent),var(--accent-2));color:white}
.scene-pattern{position:fixed;right:0;top:0;width:45vw;height:100vh;opacity:.06;pointer-events:none}
.site-header{backdrop-filter:saturate(120%) blur(4px);position:sticky;top:0;background:rgba(255,255,255,0.6);border-bottom:1px solid rgba(16,24,32,0.04);z-index:20}
.hero{padding:80px 0 40px;background:linear-gradient(180deg,transparent,rgba(0,0,0,0.02))}
.hero-head{font-size:2rem;margin:0 0 12px}
.hero-sub{margin:0 0 18px;color:#334}
.hero-actions{display:flex;gap:12px}
.btn{display:inline-block;padding:10px 14px;border-radius:10px;text-decoration:none;border:1px solid transparent}
.btn.primary{background:var(--accent);color:#fff}
.btn.ghost{background:transparent;border-color:rgba(16,24,32,0.06)}
.two-col{display:grid;grid-template-columns:1fr 360px;gap:var(--gap);align-items:start}
.story h2,.framework h2,.offers h2,.pricing h2{margin-top:0}
.frame-list{list-style:decimal;margin-left:1.2rem}
.muted{color:rgba(17,18,34,0.55);font-size:0.95rem}
.pricing-grid{display:flex;gap:16px;flex-wrap:wrap}
.card{background:var(--card);padding:18px;border-radius:12px;box-shadow:0 6px 18px rgba(17,18,34,0.04);flex:1;min-width:220px}
.card.featured{border:2px solid rgba(108,136,102,0.12)}
.price{font-weight:700;font-size:1.25rem}
.testimonials blockquote{background:linear-gradient(90deg,rgba(108,136,102,0.04),transparent);padding:14px;border-radius:10px}
.final-cta{padding:40px 0}
.site-footer{border-top:1px solid rgba(16,24,32,0.04);padding:18px 0;background:transparent}
.site-footer .container{display:flex;justify-content:space-between;align-items:center}
.planner{background:linear-gradient(180deg,rgba(255,255,255,0.9),#fff);padding:16px;border-radius:12px;box-shadow:0 8px 20px rgba(17,18,34,0.06)}
.planner label{display:block;margin-bottom:10px;font-size:0.95rem}
.planner textarea{width:100%;padding:8px;border-radius:8px;border:1px solid rgba(16,24,32,0.06);resize:vertical}
.planner input[type=range]{width:100%}
.planner .range-value{font-size:0.9rem;color:rgba(17,18,34,0.6);margin-top:6px}
.planner-actions{display:flex;gap:10px;margin-top:6px}
@media (max-width:880px){
  .two-col{grid-template-columns:1fr}
  .scene-pattern{display:none}
  .nav ul{gap:8px}
}
/* Reveal animation */
.reveal{opacity:0;transform:translateY(18px);transition:opacity .6s ease,transform .6s ease}
.reveal.is-visible{opacity:1;transform:translateY(0)}
@media (prefers-reduced-motion:reduce){
  .reveal{transition:none;opacity:1;transform:none}
}
/* Small utilities */
.note{font-size:0.9rem;color:rgba(17,18,34,0.6)}
.range-value{display:flex;justify-content:flex-end}
/* accessibility focus */
a:focus,button:focus,input:focus,textarea:focus{outline:3px solid rgba(108,136,102,0.18);outline-offset:2px}
"} 
{"path":"assets/js/main.js","content":"(function(){
  // Simple utilities
  function q(sel,ctx){return (ctx||document).querySelector(sel)}
  function qa(sel,ctx){return Array.from((ctx||document).querySelectorAll(sel))}

  // Year in footer
  q('#yr').textContent = new Date().getFullYear();

  // Scroll-trigger reveal respecting prefers-reduced-motion
  var prefersReduced = window.matchMedia('(prefers-reduced-motion: reduce)').matches;
  var reveals = qa('[data-reveal]');
  if(prefersReduced){
    reveals.forEach(function(el){el.classList.add('is-visible')});
  } else if('IntersectionObserver' in window){
    var obs = new IntersectionObserver(function(entries){
      entries.forEach(function(e){
        if(e.isIntersecting){
          e.target.classList.add('is-visible');
          obs.unobserve(e.target);
        }
      });
    },{threshold:0.12});
    reveals.forEach(function(r){obs.observe(r)});
  } else {
    // fallback: show all
    reveals.forEach(function(el){el.classList.add('is-visible')});
  }

  // Session Planner
  var sp = {
    concern: q('#sp-concern'),
    goals: qa('input[name="goal"]'),
    time: q('#sp-time'),
    timeVal: q('#sp-time-val'),
    budget: q('#sp-budget'),
    mods: {
      coach: q('#mod-coach'),
      nutrition: q('#mod-nutrition'),
      movement: q('#mod-movement'),
      tele: q('#mod-tele')
    },
    genBtn: q('#sp-generate'),
    copyBtn: q('#sp-copy'),
    summary: q('#sp-summary')
  };

  // reflect time range
  function updateTime(){sp.timeVal.textContent = sp.time.value}
  sp.time.addEventListener('input', updateTime);
  updateTime();

  function collectGoals(){
    return sp.goals.filter(function(g){return g.checked}).map(function(g){return g.value});
  }
  function collectMods(){
    var out = [];
    if(sp.mods.coach.checked) out.push('Coaching');
    if(sp.mods.nutrition.checked) out.push('Nutrition');
    if(sp.mods.movement.checked) out.push('Movement & breath');
    if(sp.mods.tele.checked) out.push('Tele check-ins');
    return out;
  }

  function generatePlanText(){
    var concern = sp.concern.value.trim() || '[No concern provided]';
    var goals = collectGoals();
    var time = sp.time.value;
    var budget = sp.budget.value;
    var mods = collectMods();

    var goalLine = goals.length ? goals.join(', ') : 'Unspecified goals';
    var modLine = mods.length ? mods.join(', ') : 'No modality preference';

    var budgetNote = {
      low: 'Intro-level recommendations and low-cost resources.',
      medium: 'Mixed model: focused sessions with select check-ins.',
      high: 'Flexible scope with more frequent touchpoints.'
    }[budget] || '';

    var plan = [];
    plan.push('Session planner summary');
    plan.push('-----------------------');
    plan.push('Primary concern: ' + concern);
    plan.push('Goals: ' + goalLine);
    plan.push('Weekly time available: ' + time + ' hours');
    plan.push('Modality preferences: ' + modLine);
    plan.push('Budget framing: ' + budget + ' – ' + budgetNote);
    plan.push('');

    // Small recommended starter plan (educational tone)
    plan.push('Suggested starter sequence (educational):');
    if(time >= 5){
      plan.push('- Weekly 45–60 min session for first 4 weeks; daily 10–20 minute practices.');
    } else if(time >= 2){
      plan.push('- Two 45 min sessions across four weeks with short daily anchors (5–10 min).');
    } else if(time > 0){
      plan.push('- One focused consult; short, tangible tasks you can test 3x/week.');
    } else {
      plan.push('- Brief consult to prioritize one low-effort experiment to try.');
    }

    plan.push('- Track 2 simple signals (sleep quality, energy, mood) and revisit after 4 weeks.');
    plan.push('');
    plan.push('Notes for first visit:');
    plan.push('- Bring a recent 3-day log of sleep and main meals if available.');
    plan.push('- Be ready to pick one small experiment to try in week 1.');
    plan.push('');
    plan.push('This summary is for educational planning. It is not medical advice.');

    return plan.join('\n');
  }

  sp.genBtn.addEventListener('click', function(){
    try{
      var txt = generatePlanText();
      sp.summary.value = txt;
      sp.copyBtn.disabled = false;
    }catch(e){
      sp.summary.value = 'Unable to generate plan at this time.';
    }
  });

  sp.copyBtn.addEventListener('click', function(){
    var txt = sp.summary.value;
    if(!txt) return;
    navigator.clipboard && navigator.clipboard.writeText ? navigator.clipboard.writeText(txt).then(function(){
      sp.copyBtn.textContent = 'Copied!';
      setTimeout(function(){sp.copyBtn.textContent = 'Copy summary'},1500);
    },function(){
      fallbackCopy(txt);
    }) : fallbackCopy(txt);
  });

  function fallbackCopy(text){
    var ta = document.createElement('textarea');
    ta.value = text;document.body.appendChild(ta);ta.select();
    try{document.execCommand('copy');
      sp.copyBtn.textContent = 'Copied!';
      setTimeout(function(){sp.copyBtn.textContent = 'Copy summary'},1500);
    }catch(e){alert('Copy failed — select and copy the text manually.')}
    document.body.removeChild(ta);
  }

})();"} 
